  assert.equal(result[0].rate, 21);
  // 1 × 9500 + 2 × 9500 = 28500 cents (no discounts)
  assert.equal(result[0].base, 28500);
  // VAT 21% of 28500 = 5985 cents
  assert.equal(result[0].vat, 5985);
});

test('vatSummary: aggregates multiple invoices', () => {
