  // inv1: 1 × 9500 = 9500
  // inv2: 2 × 9500 = 19000
  // Total base: 28500
  assert.equal(result[0].base, 28500);
  assert.equal(result[0].vat, 5985);
});

test('vatSummary: handles multiple VAT rates across invoices', () => {
