      { sku: 'BOOK-DESIGN', qty: 1, discountPercent: 20 }, // 9% VAT, 2490 cents
    ],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  const result = vatSummary([issued.value]);

  assert.equal(result.length, 2);

  const rate21 = result.find((r) => r.rate === 21);
  const rate9 = result.find((r) => r.rate === 9);

  // DEV-HOUR: 2 × 9500 = 19000, discount 10% = 1900, base = 17100
  assert.equal(rate21.base, 17100);

  // BOOK-DESIGN: 1 × 2490 = 2490, discount 20% = 498, base = 1992
  assert.equal(rate9.base, 1992);
});

