    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // Due date is 2026-10-31, asOf is same day
  const result = lateFee(issued.value, '2026-10-31');

  assert.equal(result, 0);
});

test('lateFee: calculates fee for 1 day overdue', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // Due date is 2026-10-31, asOf is 2026-11-01 = 1 day overdue
  // Due is 22990 cents
  // Fee = 22990 * 1 * 0.0004 = 9.196 cents → 9 cents
  const result = lateFee(issued.value, '2026-11-01');

  assert.equal(result, 9);
});

test('lateFee: calculates fee for multiple days overdue', () => {
