  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // Due date is 2026-10-31, asOf is 2026-11-15 = 15 days overdue
  // Due is 22990 cents
  // Fee = 22990 * 15 * 0.0004 = 137.94 cents → 138 cents
  const result = lateFee(issued.value, '2026-11-15');

  assert.equal(result, 138);
});

test('lateFee: accounts for partial payments', () => {
