    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // Total is 11495 cents (9500 + 1995 VAT)
  // 10 days overdue, fee = 11495 * 10 * 0.0004 = 45.98 cents → 46 cents
  const result = lateFee(issued.value, '2026-11-10');

  assert.equal(result, 46);
});

test('lateFee: calculates correctly for large amounts', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BRAND-BOOK', qty: 1 }], // 245000 cents
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // BRAND-BOOK: 245000 cents, VAT 21% = 51450 cents, total = 296450 cents
  // 10 days overdue, fee = 296450 * 10 * 0.0004 = 1185.8 cents → 1186 cents
  const result = lateFee(issued.value, '2026-11-10');

  assert.equal(result, 1186);
});

test('lateFee: calculates correctly for small amounts', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
