  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // STICKER: 50 cents, VAT 21% = 10.5 cents → 10 cents (banker's rounding), total = 60 cents
  // Due date 2026-10-31, asOf 2026-12-31 = 61 days overdue
  // fee = 60 * 61 * 0.0004 = 1.464 cents → 1 cent
  const result = lateFee(issued.value, '2026-12-31');

  assert.equal(result, 1);
});

test('lateFee: handles invoice with discount', () => {
