    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2, discountPercent: 10 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // DEV-HOUR: 2 × 9500 = 19000, discount 10% = 1900, after discount = 17100
  // VAT 21% of 17100 = 3591, total = 20691
  // 5 days overdue, fee = 20691 * 5 * 0.0004 = 41.382 cents → 41 cents
  const result = lateFee(issued.value, '2026-11-05');

  assert.equal(result, 41);
});

test('lateFee: calculates based on days from dueDate to asOf', () => {
  const invResult = createInvoice({
