    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv1Result.ok, true);
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv2Result.ok, true);
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const inv3Result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv3Result.ok, true);
  const inv3Issued = issueInvoice(inv3Result.value, [inv1Issued.value.number, inv2Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value, inv3Issued.value];
  const result = dashboard(invoices, '2026-11-15');

  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-002'); // Highest due
  assert.equal(result.topCustomers[1].customerId, 'C-001');
  assert.equal(result.topCustomers[2].customerId, 'C-003');
