test('dashboard: filters to only top 3 customers', () => {
  const invoices = [];
  const existingNumbers = [];

  for (let i = 1; i <= 5; i++) {
    const invResult = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: i }],
    });
    assert.equal(invResult.ok, true);
    const issued = issueInvoice(invResult.value, existingNumbers);
    invoices.push(issued.value);
    existingNumbers.push(issued.value.number);
  }

  const result = dashboard(invoices, '2026-11-15');

  assert.equal(result.topCustomers.length, 3);
  // Should be sorted highest due first
  assert(result.topCustomers[0].due >= result.topCustomers[1].due);
  assert(result.topCustomers[1].due >= result.topCustomers[2].due);
});

