test('vatSummary: returns one entry per VAT rate', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // VAT 21%
      { sku: 'PRINT-A4', qty: 1 }, // VAT 9%
    ],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  const result = vatSummary([issued.value]);

  assert.equal(result.length, 2);
