1	import { roundCents } from './money.js';
2	
3	/**
4	 * Calculate the total amount for one line (qty × unitPrice, in cents).
5	 * @param {{ qty: number, unitPrice: number }} line
6	 * @returns {number}
7	 */
8	export function lineTotal(line) {
9	  return line.qty * line.unitPrice;
10	}
11	
12	/**
13	 * Calculate invoice totals (subtotal, discount, VAT, voucher, and total in cents).
14	 * Bulk discount (2.5%) applies on lines with qty >= 10, after any line/tier discount.
15	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
16	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
17	 */
18	export function invoiceTotals(invoice) {
19	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
20	  const discount = invoice.lines.reduce((sum, line) => {
21	    const lineTotal_ = lineTotal(line);
22	    const lineDiscount = roundCents(lineTotal_ * (line.discountPercent ?? 0) / 100);
23	    const lineAfterDiscount = Math.max(0, lineTotal_ - lineDiscount);
24	    // Bulk discount: 2.5% extra on lines with 10+ units, applied after line discount
25	    const bulkDiscount = line.qty >= 10 ? roundCents(lineAfterDiscount * 2.5 / 100) : 0;
26	    return sum + Math.max(0, lineDiscount) + Math.max(0, bulkDiscount);
27	  }, 0);
28	  const vat = invoice.lines.reduce((sum, line) => {
29	    const lineTotal_ = lineTotal(line);
30	    const lineDiscount = roundCents(lineTotal_ * (line.discountPercent ?? 0) / 100);
31	    const lineAfterFirstDiscount = Math.max(0, lineTotal_ - lineDiscount);
32	    // Bulk discount applied after line discount
33	    const bulkDiscount = line.qty >= 10 ? roundCents(lineAfterFirstDiscount * 2.5 / 100) : 0;
34	    const lineAfterDiscount = Math.max(0, lineAfterFirstDiscount - bulkDiscount);
35	    const lineVat = roundCents(lineAfterDiscount * line.vatRate / 100);
36	    return sum + Math.max(0, lineVat);
37	  }, 0);
38	  const voucher = invoice.voucher?.amount ?? 0;
39	  const total = Math.max(0, subtotal - discount + vat - voucher);
